"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

TILE_ENTER_COST: dict[str, int] = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = _locate_tile(grid, "S")
    goal = _locate_tile(grid, "G")
    if start is None or goal is None:
        return None

    best_cost: dict[Cell, int] = {start: 0}
    came_from: dict[Cell, Cell] = {}
    frontier: list[tuple[int, Cell]] = [(0, start)]
    while frontier:
        cost, cell = heapq.heappop(frontier)
        if cell == goal:
            return _rebuild_path(came_from, start, goal)
        if cost > best_cost[cell]:
            continue  # stale heap entry: a cheaper route was queued later
        for neighbour, enter_cost in _open_neighbours(grid, cell):
            new_cost = cost + enter_cost
            if new_cost < best_cost.get(neighbour, new_cost + 1):
                best_cost[neighbour] = new_cost
                came_from[neighbour] = cell
                heapq.heappush(frontier, (new_cost, neighbour))
    return None


def _locate_tile(grid: list[str], tile: str) -> Cell | None:
    for row, line in enumerate(grid):
        col = line.find(tile)
        if col != -1:
            return (row, col)
    return None


def _open_neighbours(grid: list[str], cell: Cell) -> list[tuple[Cell, int]]:
    row, col = cell
    neighbours: list[tuple[Cell, int]] = []
    for next_row, next_col in ((row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)):
        # Bounds use each row's own length so jagged maps do not raise IndexError.
        if not (0 <= next_row < len(grid) and 0 <= next_col < len(grid[next_row])):
            continue
        tile = grid[next_row][next_col]
        if tile == "#":
            continue
        if tile not in TILE_ENTER_COST:
            raise ValueError(
                f"unknown tile {tile!r} at ({next_row}, {next_col}); expected one of '.DSG#'"
            )
        neighbours.append(((next_row, next_col), TILE_ENTER_COST[tile]))
    return neighbours


def _rebuild_path(came_from: dict[Cell, Cell], start: Cell, goal: Cell) -> list[Cell]:
    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()
    return path


