import unittest

from pathfind import find_path


class VisibleTest(unittest.TestCase):
    def test_straight_corridor(self):
        self.assertEqual(find_path(["S..G"]), [(0, 0), (0, 1), (0, 2), (0, 3)])

    def test_detour_beats_fewer_steps_through_doors(self):
        self.assertEqual(
            find_path(["SDDG", "...."]),
            [(0, 0), (1, 0), (1, 1), (1, 2), (1, 3), (0, 3)],
        )

    def test_door_beats_longer_detour(self):
        self.assertEqual(
            find_path(["SD.G", ".##.", ".##.", "...."]),
            [(0, 0), (0, 1), (0, 2), (0, 3)],
        )

    def test_walled_off_goal_returns_none(self):
        self.assertIsNone(find_path(["S#G"]))


if __name__ == "__main__":
    unittest.main()

